INSERT INTO imoveis (id, codigo, titulo, finalidade, tipo, preco, iptu, condominio, observacoes, descricao, cidade_bairro, dormitorios, banheiros, vagas, aceita_financiamento, aceita_permuta, destaque, status, created_at, updated_at) VALUES ('1', 'PNA-00001', 'Magnifico Apartamento de Luxo com Vista Mar frontal', 'venda', 'apartamento', '500000.00', '520.00', '980.00', 'Varanda e cozinha gourmet integradas, acabamentos de alto padrão, suite master. Primeira linha da praia.', 'Apresentamos um exclusivo apartamento de alto padrão no prestigiado Edifício Solar da Praia Grande, localizado de frente para o mar. Este imóvel de luxo destaca-se pela sua deslumbrante vista panorâmica para a orla, visível a partir da espaçosa varanda, da sala de estar e da suite principal.\r\nO apartamento dispõe de um conceito aberto, com uma sala de estar e de jantar perfeitamente integradas a uma moderna cozinha gourmet, utilizando acabamentos de excelência em madeira e pedra que garantem sofisticação e continuidade aos espaços. A área íntima é composta por dois dormitórios, sendo um deles uma magnífica suite master com acesso direto à varanda e um segundo quarto com vista lateral para o mar. Conta ainda com duas casas de banho de luxo com acabamentos modernos.\r\n\r\nIdeal para quem procura conforto, elegância e a tranquilidade de viver de frente para a praia. O edifício oferece infraestrutura completa. Não perca esta excelente oportunidade!', 'Canto do Forte - Praia Grande / SP', '2', '3', '6', '1', '0', '1', 'ativo', '2026-09-24 11:00:08', '2026-09-24 12:35:33');
